/* Sessions and roles. Generated by Chakram. Passwords use scrypt; sessions are opaque cookies stored server-side. */
import { randomBytes, scryptSync, timingSafeEqual } from 'node:crypto';
import type { Context, MiddlewareHandler } from 'hono';
import { getCookie, setCookie, deleteCookie } from 'hono/cookie';
import type { Store, User } from './store.js';

export type Role = 'owner' | 'member' | 'viewer';
export const SESSION_COOKIE = 'app_session';
const SESSION_DAYS = 14;
const RANK: Record<Role, number> = { viewer: 0, member: 1, owner: 2 };

export function hashPassword(password: string): string {
  const salt = randomBytes(16).toString('hex');
  return `${salt}:${scryptSync(password, salt, 64).toString('hex')}`;
}

export function verifyPassword(password: string, stored: string): boolean {
  const [salt, hash] = stored.split(':');
  if (!salt || !hash) return false;
  const a = Buffer.from(hash, 'hex');
  const b = scryptSync(password, salt, 64);
  return a.length === b.length && timingSafeEqual(a, b);
}

export type Vars = { user: User };

export async function startSession(c: Context, store: Store, user: User): Promise<void> {
  const token = randomBytes(32).toString('hex');
  const expires = new Date(Date.now() + SESSION_DAYS * 86_400_000);
  await store.createSession(token, user.id, expires.toISOString());
  setCookie(c, SESSION_COOKIE, token, { httpOnly: true, sameSite: 'Lax', path: '/', secure: process.env.NODE_ENV === 'production', expires });
}

export async function endSession(c: Context, store: Store): Promise<void> {
  const token = getCookie(c, SESSION_COOKIE);
  if (token) await store.deleteSession(token);
  deleteCookie(c, SESSION_COOKIE, { path: '/' });
}

export async function currentUser(c: Context, store: Store): Promise<User | null> {
  const token = getCookie(c, SESSION_COOKIE);
  if (!token) return null;
  const session = await store.findSession(token);
  if (!session || new Date(session.expiresAt).getTime() < Date.now()) return null;
  return store.findUserById(session.userId);
}

/** Every protected route: a valid session, and at least `role`. UI hiding is not access control. */
export function requireRole(store: Store, role: Role): MiddlewareHandler<{ Variables: Vars }> {
  return async (c, next) => {
    const user = await currentUser(c, store);
    if (!user) return c.json({ code: 'unauthenticated', message: 'Sign in to continue', retryable: false }, 401);
    if (RANK[user.role] < RANK[role]) return c.json({ code: 'forbidden', message: `This action needs the ${role} role`, retryable: false }, 403);
    c.set('user', user);
    await next();
  };
}
